/* 获取某本词书的全部单词 */
function getBookWords(bookId) {
  return WORDS[bookId] || [];
}

/* 按 id 查词（跨词书） */
function findWord(wordId) {
  for (const bookId of Object.keys(WORDS)) {
    const hit = WORDS[bookId].find((w) => w.id === wordId);
    if (hit) return { ...hit, bookId };
  }
  return null;
}
